sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float stripWidth;
uniform float angle;
uniform float sourcePos;
uniform float alternate;
uniform float shift;
uniform float scroll;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float a = radians(angle);
    float2 dir = float2(cos(a), sin(a));
    float2 nrm = float2(-dir.y, dir.x);
    float along = dot(coord - size * 0.5, dir) + time * scroll;
    float across = dot(coord - size * 0.5, nrm);
    float idx = floor(along / stripWidth);
    float f = fract(along / stripWidth);
    if (alternate > 0.5 && mod(idx, 2.0) > 0.5) f = 1.0 - f;
    float srcAlong = (sourcePos - 0.5) * length(size) + (f - 0.5) * stripWidth;
    float2 q = size * 0.5 + dir * srcAlong + nrm * (across + idx * shift);
    return fin(c, tex(q), opacity);
}
